mapper.select:
SELECT * FROM ( SELECT 'in' AS recordType, r.bill_no AS billNo, r.material_id AS materialId, r.batch_no AS batchNo, r.in_num AS num, r.in_user AS operator, r.in_time AS opTime FROM in_record r
UNION ALL SELECT 'out' AS recordType, r.outbound_code AS billNo, r.material_id AS materialId, r.batch_no AS batchNo, r.out_num AS num, r.out_user AS operator, r.out_time AS opTime FROM tb_out_record r
) t
WHERE t.recordType = #{type}
ORDER BY opTime DESC

SELECT * FROM ( SELECT 'in' AS recordType, r.bill_no AS billNo, r.material_id AS materialId, r.batch_no AS batchNo, r.in_num AS num, r.in_user AS operator, r.in_time AS opTime FROM in_record r
UNION ALL SELECT 'out' AS recordType, r.outbound_code AS billNo, r.material_id AS materialId, r.batch_no AS batchNo, r.out_num AS num, r.out_user AS operator, r.out_time AS opTime FROM tb_out_record r
) t
WHERE t.recordType = #{type}
ORDER BY opTime DESC
